function metaValue(report,key,legacy=''){const m=report.summary.meta||{};return String(m[key]??m[legacy]??'')}
function reportDate(r){const m=r.summary.meta||{},explicit=String(m.run_date||'');if(/^\d{4}-\d{2}-\d{2}$/.test(explicit))return explicit;const match=String(r.id||'').match(/\/(\d{4})(\d{2})(\d{2})-/);return match?`${match[1]}-${match[2]}-${match[3]}`:''}
