function comparisonModeHelp(){const messages={engines:'Choose one engine run first. Candidates are other engines with the same test plan, run type and benchmark identity; dialect-specific query filenames may differ.',regression:'Choose the older run first. Candidates are limited to the same engine, test plan and query file.',load_impact:'Compare the same query workload on one engine under different load patterns, such as sequential versus concurrency. This measures workload impact, not a build regression.',reference:'Baseline choices are active references. Candidates are compatible newer runs from the same engine.',reference_engines:'Both choices are promoted reference baselines from different engines with the same benchmark identity.'};$('comparisonModeHelp').textContent=messages[$('comparisonMode').value]}
